import { test, expect } from '@playwright/test';

test.describe('Filter List by Multiple Statuses', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/list');
  });

  test('should filter list by multiple statuses simultaneously', async ({ page }) => {
    // Verify list is visible
    const listContainer = page.getByRole('region', { name: /list/i });
    await expect(listContainer).toBeVisible();

    // Verify initial items are displayed
    const initialItems = page.getByRole('listitem');
    await expect(initialItems).toHaveCount(10);

    // Open filter modal
    const filterButton = page.getByRole('button', { name: /filter/i });
    await filterButton.click();

    // Verify filter modal is visible
    const filterModal = page.getByRole('dialog', { name: /filter options/i });
    await expect(filterModal).toBeVisible();

    // Select 'Active' status filter
    const activeStatusCheckbox = page.getByLabel(/active/i);
    await activeStatusCheckbox.click();

    // Select 'Pending' status filter
    const pendingStatusCheckbox = page.getByLabel(/pending/i);
    await pendingStatusCheckbox.click();

    // Verify both checkboxes are checked
    await expect(activeStatusCheckbox).toBeChecked();
    await expect(pendingStatusCheckbox).toBeChecked();

    // Apply filters
    const applyButton = page.getByRole('button', { name: /apply filters/i });
    await applyButton.click();

    // Verify filter modal is closed
    await expect(filterModal).not.toBeVisible();

    // Verify list is updated with filtered items
    const filteredItems = page.getByRole('listitem');
    await expect(filteredItems).toHaveCount(5);

    // Verify filtered items contain expected statuses
    const item1 = page.getByRole('listitem').first();
    const item2 = page.getByRole('listitem').nth(1);
    const item3 = page.getByRole('listitem').nth(2);

    const statusBadge1 = page.getByText('Active');
    const statusBadge2 = page.getByText('Pending');
    const statusBadge3 = page.getByText('Active');

    await expect(statusBadge1).toBeVisible();
    await expect(statusBadge2).toBeVisible();
    await expect(statusBadge3).toBeVisible();
  });

  test('should handle no results when filtering with multiple statuses', async ({ page }) => {
    // Open filter modal
    const filterButton = page.getByRole('button', { name: /filter/i });
    await filterButton.click();

    // Select 'Archived' status filter
    const archivedStatusCheckbox = page.getByLabel(/archived/i);
    await archivedStatusCheckbox.click();

    // Select 'Deleted' status filter
    const deletedStatusCheckbox = page.getByLabel(/deleted/i);
    await deletedStatusCheckbox.click();

    // Apply filters
    const applyButton = page.getByRole('button', { name: /apply filters/i });
    await applyButton.click();

    // Verify no results message is displayed
    const noResultsMessage = page.getByText(/no results found/i);
    await expect(noResultsMessage).toBeVisible();

    // Verify list container is empty
    const listContainer = page.getByRole('region', { name: /list/i });
    const filteredItems = page.getByRole('listitem');
    await expect(filteredItems).toHaveCount(0);

    // Verify clear filters button is visible
    const clearButton = page.getByRole('button', { name: /clear filters/i });
    await expect(clearButton).toBeVisible();

    // Clear filters
    await clearButton.click();

    // Verify filter modal is visible again
    await expect(page.getByRole('dialog', { name: /filter options/i })).toBeVisible();

    // Verify no status checkboxes are checked
    await expect(archivedStatusCheckbox).not.toBeChecked();
    await expect(deletedStatusCheckbox).not.toBeChecked();
  });
});
